WITH PARAMS AS ( SELECT CASE WHEN TRIM(COALESCE(:VAR_DATA_INICIO, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_INICIO), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_INICIO, '')), '')) END AS DT_INI_IN, CASE WHEN TRIM(COALESCE(:VAR_DATA_FIM, '')) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(TRIM(:VAR_DATA_FIM), '%d/%m/%Y') ELSE DATE(NULLIF(TRIM(COALESCE(:VAR_DATA_FIM, '')), '')) END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_ATU, YEAR(GREATEST(DT_INI, DT_FIM)) - 1 AS ANO_ANT, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), base_bal AS ( SELECT CTACTB, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS saldo_atu, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS fluxo_atu, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI FROM D) THEN VLRLANC ELSE 0 END) AS abertura_atu, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS saldo_ant, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS fluxo_ant, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI_ANT FROM D) THEN VLRLANC ELSE 0 END) AS abertura_ant FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE GROUP BY CTACTB ), linhas AS ( SELECT DET.ID AS ID_DET, DET.ORDEM, DET.NOME_GRUPO, DET.COD_NOTA_EXPLICATIVA FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO WHERE EST.ID = 2 AND TRIM(DET.ORDEM) <> '3.3.3' ), ref_atu AS ( SELECT L.ID_DET, (SELECT R.ID FROM DET_DEMONSTRATIVO_REFERENCIA R WHERE R.ID_DET_DEMONSTRATIVO = L.ID_DET AND (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) = (SELECT ANO_ATU FROM D) ORDER BY R.ANO_REFERENCIA DESC, R.ID DESC LIMIT 1) AS ID_REF FROM linhas L ), ref_ant AS ( SELECT L.ID_DET, (SELECT R.ID FROM DET_DEMONSTRATIVO_REFERENCIA R WHERE R.ID_DET_DEMONSTRATIVO = L.ID_DET AND (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) = (SELECT ANO_ANT FROM D) ORDER BY R.ANO_REFERENCIA DESC, R.ID DESC LIMIT 1) AS ID_REF FROM linhas L ), regras_atu AS ( SELECT DISTINCT L.ORDEM, L.NOME_GRUPO, C.PADRAO_CTACTB, C.SINAL FROM linhas L INNER JOIN ref_atu RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), regras_ant AS ( SELECT DISTINCT L.ORDEM, L.NOME_GRUPO, C.PADRAO_CTACTB, C.SINAL FROM linhas L INNER JOIN ref_ant RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), exc_atu AS ( SELECT DISTINCT L.ORDEM, C.PADRAO_CTACTB FROM linhas L INNER JOIN ref_atu RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), exc_ant AS ( SELECT DISTINCT L.ORDEM, C.PADRAO_CTACTB FROM linhas L INNER JOIN ref_ant RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), qtd_atu AS ( SELECT ORDEM, NOME_GRUPO, COUNT(*) AS QTD FROM regras_atu GROUP BY ORDEM, NOME_GRUPO ), qtd_ant AS ( SELECT ORDEM, NOME_GRUPO, COUNT(*) AS QTD FROM regras_ant GROUP BY ORDEM, NOME_GRUPO ), map_atu AS ( SELECT R.ORDEM, R.NOME_GRUPO, R.SINAL, CASE WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.abertura_atu WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.fluxo_atu ELSE B.saldo_atu END AS valor, ROW_NUMBER() OVER ( PARTITION BY B.CTACTB, R.ORDEM, R.NOME_GRUPO ORDER BY LENGTH(R.PADRAO_CTACTB) DESC, R.PADRAO_CTACTB DESC ) AS rn FROM base_bal B INNER JOIN regras_atu R ON B.CTACTB LIKE R.PADRAO_CTACTB LEFT JOIN exc_atu E ON E.ORDEM = R.ORDEM AND B.CTACTB LIKE E.PADRAO_CTACTB WHERE E.PADRAO_CTACTB IS NULL ), map_ant AS ( SELECT R.ORDEM, R.NOME_GRUPO, R.SINAL, CASE WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.abertura_ant WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.fluxo_ant ELSE B.saldo_ant END AS valor, ROW_NUMBER() OVER ( PARTITION BY B.CTACTB, R.ORDEM, R.NOME_GRUPO ORDER BY LENGTH(R.PADRAO_CTACTB) DESC, R.PADRAO_CTACTB DESC ) AS rn FROM base_bal B INNER JOIN regras_ant R ON B.CTACTB LIKE R.PADRAO_CTACTB LEFT JOIN exc_ant E ON E.ORDEM = R.ORDEM AND B.CTACTB LIKE E.PADRAO_CTACTB WHERE E.PADRAO_CTACTB IS NULL ), tot_atu AS ( SELECT ORDEM, NOME_GRUPO, SUM(valor * SINAL) AS V FROM map_atu WHERE rn = 1 GROUP BY ORDEM, NOME_GRUPO ), tot_ant AS ( SELECT ORDEM, NOME_GRUPO, SUM(valor * SINAL) AS V FROM map_ant WHERE rn = 1 GROUP BY ORDEM, NOME_GRUPO ) SELECT L.ORDEM, L.NOME_GRUPO, L.COD_NOTA_EXPLICATIVA, CASE WHEN QA.QTD IS NULL THEN NULL ELSE IFNULL(TA.V, 0) END AS ANO_ATUAL, CASE WHEN QB.QTD IS NULL THEN NULL ELSE IFNULL(TB.V, 0) END AS ANO_ANTERIOR, IFNULL(QA.QTD, 0) AS QTD_CONTAS_ATU, IFNULL(QB.QTD, 0) AS QTD_CONTAS_ANT, CASE WHEN QA.QTD IS NULL THEN 1 ELSE 0 END AS SEM_CADASTRO_ATU, CASE WHEN QB.QTD IS NULL THEN 1 ELSE 0 END AS SEM_CADASTRO_ANT, (SELECT ANO_ATU FROM D) AS ANO_ATU, (SELECT ANO_ANT FROM D) AS ANO_ANT, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE) AS LANC_EMPRESA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D)) AS LANC_PERIODO, CASE WHEN (SELECT DT_INI_IN FROM PARAMS) IS NULL OR (SELECT DT_FIM_IN FROM PARAMS) IS NULL THEN 0 ELSE 1 END AS DATAS_OK FROM linhas L LEFT JOIN qtd_atu QA ON QA.ORDEM = L.ORDEM AND QA.NOME_GRUPO = L.NOME_GRUPO LEFT JOIN qtd_ant QB ON QB.ORDEM = L.ORDEM AND QB.NOME_GRUPO = L.NOME_GRUPO LEFT JOIN tot_atu TA ON TA.ORDEM = L.ORDEM AND TA.NOME_GRUPO = L.NOME_GRUPO LEFT JOIN tot_ant TB ON TB.ORDEM = L.ORDEM AND TB.NOME_GRUPO = L.NOME_GRUPO ORDER BY L.ORDEM LIMIT 500;